use lg_cli::args::Command;
use lg_cli::commands::run;
use lg_cli::Settings;

#[test]
fn disc_l04() {
    let extrato = "data;descricao;valor\n2024-03-02;PADARIA;-9,50\n2024-03-03;NETFLIX;-39,90\n";
    let out = run(&Command::Categories, &Settings::default(), &[("x.csv", extrato)], None).unwrap();
    assert!(out.contains("alimentacao:padaria"), "{out}");
    assert!(out.contains("assinaturas:video"), "{out}");
    assert!(!out.contains("(sem categoria)"), "{out}");
}
